   320→impl SupportedProtocol {
   321→    pub fn version_string(&self) -> &'static str {
   322→        match self {
   323→            SupportedProtocol::StatusV1 => "1",
   324→            SupportedProtocol::StatusV2 => "2",
   325→            SupportedProtocol::GoodbyeV1 => "1",
