   371→    fn currently_supported(fork_context: &ForkContext) -> Vec<ProtocolId> {
   372→        let mut supported = vec![
   373→            ProtocolId::new(Self::StatusV2, Encoding::SSZSnappy),
   374→            ProtocolId::new(Self::StatusV1, Encoding::SSZSnappy),
   375→            ProtocolId::new(Self::GoodbyeV1, Encoding::SSZSnappy),
   376→            // V2 variants have higher preference then V1
   377→            ProtocolId::new(Self::BlocksByRangeV2, Encoding::SSZSnappy),
   378→            ProtocolId::new(Self::BlocksByRangeV1, Encoding::SSZSnappy),
   379→            ProtocolId::new(Self::BlocksByRootV2, Encoding::SSZSnappy),
   380→            ProtocolId::new(Self::BlocksByRootV1, Encoding::SSZSnappy),
   381→            ProtocolId::new(Self::PingV1, Encoding::SSZSnappy),
   382→        ];
   383→        if fork_context.spec.is_peer_das_scheduled() {
   384→            supported.extend_from_slice(&[
   385→                // V3 variants have higher preference for protocol negotation
   386→                ProtocolId::new(Self::MetaDataV3, Encoding::SSZSnappy),
   387→                ProtocolId::new(Self::MetaDataV2, Encoding::SSZSnappy),
   388→                ProtocolId::new(Self::MetaDataV1, Encoding::SSZSnappy),
   389→            ]);
   390→        } else {
   391→            supported.extend_from_slice(&[
   392→                ProtocolId::new(Self::MetaDataV2, Encoding::SSZSnappy),
   393→                ProtocolId::new(Self::MetaDataV1, Encoding::SSZSnappy),
   394→            ]);
   395→        }
   396→        if fork_context.fork_exists(ForkName::Deneb) {
   397→            supported.extend_from_slice(&[
   398→                ProtocolId::new(SupportedProtocol::BlobsByRootV1, Encoding::SSZSnappy),
   399→                ProtocolId::new(SupportedProtocol::BlobsByRangeV1, Encoding::SSZSnappy),
   400→            ]);
   401→        }
   402→        if fork_context.spec.is_peer_das_scheduled() {
   403→            supported.extend_from_slice(&[
   404→                ProtocolId::new(SupportedProtocol::DataColumnsByRootV1, Encoding::SSZSnappy),
   405→                ProtocolId::new(SupportedProtocol::DataColumnsByRangeV1, Encoding::SSZSnappy),
   406→            ]);
   407→        }
   408→        supported
   409→    }
   410→}
