   473→/// Tracks the types in a protocol id.
   474→#[derive(Clone, Debug)]
   475→pub struct ProtocolId {
   476→    /// The protocol name and version
   477→    pub versioned_protocol: SupportedProtocol,
   478→
   479→    /// The encoding of the RPC.
   480→    pub encoding: Encoding,
   481→
   482→    /// The protocol id that is formed from the above fields.
   483→    protocol_id: String,
   484→}
   485→
   486→impl AsRef<str> for ProtocolId {
   487→    fn as_ref(&self) -> &str {
   488→        self.protocol_id.as_ref()
   489→    }
   490→}
