   492→impl ProtocolId {
   493→    /// Returns min and max size for messages of given protocol id requests.
   494→    pub fn rpc_request_limits<E: EthSpec>(&self, spec: &ChainSpec) -> RpcLimits {
   495→        match self.versioned_protocol.protocol() {
   496→            Protocol::Status => RpcLimits::new(
   497→                <StatusMessageV1 as Encode>::ssz_fixed_len(),
   498→                <StatusMessageV2 as Encode>::ssz_fixed_len(),
   499→            ),
   500→            Protocol::Goodbye => RpcLimits::new(
   501→                <GoodbyeReason as Encode>::ssz_fixed_len(),
   502→                <GoodbyeReason as Encode>::ssz_fixed_len(),
   503→            ),
   504→            // V1 and V2 requests are the same
   505→            Protocol::BlocksByRange => RpcLimits::new(
   506→                <OldBlocksByRangeRequestV2 as Encode>::ssz_fixed_len(),
   507→                <OldBlocksByRangeRequestV2 as Encode>::ssz_fixed_len(),
   508→            ),
   509→            Protocol::BlocksByRoot => RpcLimits::new(0, spec.max_blocks_by_root_request),
   510→            Protocol::BlobsByRange => RpcLimits::new(
   511→                <BlobsByRangeRequest as Encode>::ssz_fixed_len(),
   512→                <BlobsByRangeRequest as Encode>::ssz_fixed_len(),
   513→            ),
   514→            Protocol::BlobsByRoot => RpcLimits::new(0, spec.max_blobs_by_root_request),
   515→            Protocol::DataColumnsByRoot => RpcLimits::new(0, spec.max_data_columns_by_root_request),
   516→            Protocol::DataColumnsByRange => RpcLimits::new(
   517→                DataColumnsByRangeRequest::ssz_min_len(),
   518→                DataColumnsByRangeRequest::ssz_max_len::<E>(),
   519→            ),
   520→            Protocol::Ping => RpcLimits::new(
   521→                <Ping as Encode>::ssz_fixed_len(),
   522→                <Ping as Encode>::ssz_fixed_len(),
   523→            ),
   524→            Protocol::LightClientBootstrap => RpcLimits::new(
   525→                <LightClientBootstrapRequest as Encode>::ssz_fixed_len(),
   526→                <LightClientBootstrapRequest as Encode>::ssz_fixed_len(),
   527→            ),
   528→            Protocol::LightClientOptimisticUpdate => RpcLimits::new(0, 0),
   529→            Protocol::LightClientFinalityUpdate => RpcLimits::new(0, 0),
   530→            Protocol::LightClientUpdatesByRange => RpcLimits::new(
   531→                LightClientUpdatesByRangeRequest::ssz_min_len(),
   532→                LightClientUpdatesByRangeRequest::ssz_max_len(),
   533→            ),
   534→            Protocol::MetaData => RpcLimits::new(0, 0), // Metadata requests are empty
   535→        }
   536→    }
   537→
   538→    /// Returns min and max size for messages of given protocol id responses.
   539→    pub fn rpc_response_limits<E: EthSpec>(&self, fork_context: &ForkContext) -> RpcLimits {
   540→        match self.versioned_protocol.protocol() {
   541→            Protocol::Status => RpcLimits::new(
   542→                <StatusMessageV1 as Encode>::ssz_fixed_len(),
   543→                <StatusMessageV2 as Encode>::ssz_fixed_len(),
   544→            ),
   545→            Protocol::Goodbye => RpcLimits::new(0, 0), // Goodbye request has no response
   546→            Protocol::BlocksByRange => rpc_block_limits_by_fork(fork_context.current_fork_name()),
   547→            Protocol::BlocksByRoot => rpc_block_limits_by_fork(fork_context.current_fork_name()),
   548→            Protocol::BlobsByRange => rpc_blob_limits::<E>(),
   549→            Protocol::BlobsByRoot => rpc_blob_limits::<E>(),
   550→            Protocol::DataColumnsByRoot => {
   551→                rpc_data_column_limits::<E>(fork_context.current_fork_epoch(), &fork_context.spec)
   552→            }
   553→            Protocol::DataColumnsByRange => {
   554→                rpc_data_column_limits::<E>(fork_context.current_fork_epoch(), &fork_context.spec)
   555→            }
   556→            Protocol::Ping => RpcLimits::new(
   557→                <Ping as Encode>::ssz_fixed_len(),
   558→                <Ping as Encode>::ssz_fixed_len(),
   559→            ),
   560→            Protocol::MetaData => RpcLimits::new(
   561→                <MetaDataV1<E> as Encode>::ssz_fixed_len(),
   562→                <MetaDataV3<E> as Encode>::ssz_fixed_len(),
   563→            ),
   564→            Protocol::LightClientBootstrap => {
   565→                rpc_light_client_bootstrap_limits_by_fork(fork_context.current_fork_name())
   566→            }
   567→            Protocol::LightClientOptimisticUpdate => {
   568→                rpc_light_client_optimistic_update_limits_by_fork(fork_context.current_fork_name())
   569→            }
   570→            Protocol::LightClientFinalityUpdate => {
   571→                rpc_light_client_finality_update_limits_by_fork(fork_context.current_fork_name())
   572→            }
   573→            Protocol::LightClientUpdatesByRange => {
   574→                rpc_light_client_updates_by_range_limits_by_fork(fork_context.current_fork_name())
   575→            }
   576→        }
   577→    }
