   902→/// Error in RPC Encoding/Decoding.
   903→#[derive(Debug, Clone, PartialEq, IntoStaticStr)]
   904→#[strum(serialize_all = "snake_case")]
   905→pub enum RPCError {
   906→    /// Error when decoding the raw buffer from ssz.
   907→    // NOTE: in the future a ssz::DecodeError should map to an InvalidData error
   908→    #[strum(serialize = "decode_error")]
   909→    SSZDecodeError(ssz::DecodeError),
   910→    /// IO Error.
   911→    IoError(String),
   912→    /// The peer returned a valid response but the response indicated an error.
   913→    ErrorResponse(RpcErrorResponse, String),
   914→    /// Timed out waiting for a response.
   915→    StreamTimeout,
   916→    /// Peer does not support the protocol.
   917→    UnsupportedProtocol,
   918→    /// Stream ended unexpectedly.
   919→    IncompleteStream,
   920→    /// Peer sent invalid data.
   921→    InvalidData(String),
   922→    /// An error occurred due to internal reasons. Ex: timer failure.
   923→    InternalError(&'static str),
   924→    /// Negotiation with this peer timed out.
   925→    NegotiationTimeout,
   926→    /// Handler rejected this request.
   927→    HandlerRejected,
   928→    /// We have intentionally disconnected.
   929→    Disconnected,
   930→}
   931→
   932→impl From<ssz::DecodeError> for RPCError {
   933→    #[inline]
   934→    fn from(err: ssz::DecodeError) -> Self {
   935→        RPCError::SSZDecodeError(err)
   936→    }
   937→}
   938→impl From<tokio::time::error::Elapsed> for RPCError {
   939→    fn from(_: tokio::time::error::Elapsed) -> Self {
   940→        RPCError::StreamTimeout
   941→    }
   942→}
   943→
   944→impl From<io::Error> for RPCError {
   945→    fn from(err: io::Error) -> Self {
   946→        RPCError::IoError(err.to_string())
   947→    }
   948→}
