    10→
    11→/// Auxiliary struct to aid on configuration parsing.
    12→///
    13→/// A protocol's quota is specified as `protocol_name:tokens/time_in_seconds`.
    14→#[derive(Debug, PartialEq, Eq)]
    15→struct ProtocolQuota {
    16→    protocol: Protocol,
    17→    quota: Quota,
    18→}
    19→
    20→impl Display for ProtocolQuota {
    21→    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
    22→        write!(
    23→            f,
    24→            "{}:{}/{}",
    25→            self.protocol.as_ref(),
    26→            self.quota.max_tokens,
    27→            self.quota.replenish_all_every.as_secs()
    28→        )
    29→    }
    30→}
    31→
    32→impl FromStr for ProtocolQuota {
    33→    type Err = &'static str;
    34→
    35→    fn from_str(s: &str) -> Result<Self, Self::Err> {
    36→        let (protocol_str, quota_str) = s
    37→            .split_once(':')
    38→            .ok_or("Missing ':' from quota definition.")?;
    39→        let protocol = protocol_str
    40→            .parse()
    41→            .map_err(|_parse_err| "Wrong protocol representation in quota")?;
    42→        let (tokens_str, time_str) = quota_str
    43→            .split_once('/')
    44→            .ok_or("Quota should be defined as \"n/t\" (t in seconds). Missing '/' from quota.")?;
    45→        let tokens = tokens_str
    46→            .parse()
    47→            .map_err(|_| "Failed to parse tokens from quota.")?;
    48→        let seconds = time_str
    49→            .parse::<u64>()
    50→            .map_err(|_| "Failed to parse time in seconds from quota.")?;
    51→        Ok(ProtocolQuota {
    52→            protocol,
    53→            quota: Quota {
    54→                replenish_all_every: Duration::from_secs(seconds),
    55→                max_tokens: tokens,
    56→            },
    57→        })
    58→    }
    59→}
    60→
    61→#[derive(Clone, Serialize, Deserialize, PartialEq, Eq, Debug, Default)]
    62→pub struct OutboundRateLimiterConfig(pub RateLimiterConfig);
