    72→    }
    73→}
    74→
    75→impl FromStr for InboundRateLimiterConfig {
    76→    type Err = &'static str;
    77→
    78→    fn from_str(s: &str) -> Result<Self, Self::Err> {
    79→        RateLimiterConfig::from_str(s).map(Self)
    80→    }
    81→}
    82→
    83→/// Configurations for the rate limiter.
    84→#[derive(Clone, Serialize, Deserialize, PartialEq, Eq)]
    85→pub struct RateLimiterConfig {
    86→    pub(super) ping_quota: Quota,
    87→    pub(super) meta_data_quota: Quota,
    88→    pub(super) status_quota: Quota,
    89→    pub(super) goodbye_quota: Quota,
    90→    pub(super) blocks_by_range_quota: Quota,
    91→    pub(super) blocks_by_root_quota: Quota,
    92→    pub(super) blobs_by_range_quota: Quota,
    93→    pub(super) blobs_by_root_quota: Quota,
    94→    pub(super) data_columns_by_root_quota: Quota,
    95→    pub(super) data_columns_by_range_quota: Quota,
    96→    pub(super) light_client_bootstrap_quota: Quota,
    97→    pub(super) light_client_optimistic_update_quota: Quota,
    98→    pub(super) light_client_finality_update_quota: Quota,
    99→    pub(super) light_client_updates_by_range_quota: Quota,
   100→}
   101→
   102→impl RateLimiterConfig {
   103→    pub const DEFAULT_PING_QUOTA: Quota = Quota::n_every(NonZeroU64::new(2).unwrap(), 10);
   104→    pub const DEFAULT_META_DATA_QUOTA: Quota = Quota::n_every(NonZeroU64::new(2).unwrap(), 5);
   105→    pub const DEFAULT_STATUS_QUOTA: Quota = Quota::n_every(NonZeroU64::new(5).unwrap(), 15);
   106→    pub const DEFAULT_GOODBYE_QUOTA: Quota = Quota::one_every(10);
   107→    // The number is chosen to balance between upload bandwidth required to serve
   108→    // blocks and a decent syncing rate for honest nodes. Malicious nodes would need to
